  const ratio = clamp01(hp / maxHp);
  let state = _healthBarState.get(e.id);
  if (!state) {
    const seededShow = ratio < 1 ? (now + 0.9) : -Infinity;
    state = { hp, ratio, showUntil: seededShow };
